          sectionTitle: l.section_title, // Map from DB column
          result: l.result,
          notes: l.notes,
          date: l.date
        }));
        setWorkoutLogs(mappedLogs);
      }

      // 4. Fetch Athlete Records
      const { data: recordsData } = await supabase.from('athlete_records').select('*');
      if (recordsData) {
        const mappedRecords: AthleteRecord[] = recordsData.map((r: any) => ({
          id: r.id,
          userId: r.user_id,
          category: r.category,
          exercise: r.exercise,
          value: r.value,
          unit: r.unit
        }));
        setAthleteRecords(mappedRecords);
      }

      // 5. Fetch Notifications
      if (currentUser) {
         const { data: notifData } = await supabase
           .from('app_notifications')
           .select('*')
           .or(`receiver_id.eq.${currentUser.id},receiver_id.is.null`)
           .order('created_at', { ascending: false });

         if (notifData) {
            const mappedNotifs: AppNotification[] = notifData.map((n: any) => ({
               id: n.id,
               senderId: n.sender_id,
               receiverId: n.receiver_id,
