    const { error } = await supabase.from('workout_logs').update({
       result: updatedLog.result,
       notes: updatedLog.notes
    }).eq('id', updatedLog.id);

    if (error) {
       console.error("Error updating log:", error);
       alert(`Error al actualizar log: ${error.message}`);
       // Could revert here if strict consistency needed
    }
