    if (!currentUser || currentUser.role !== 'COACH') return;
    setAllUsers(prev => prev.map(u => u.id === userId ? { ...u, isApproved: newStatus } : u));
    await supabase.from('app_users').update({ is_approved: newStatus }).eq('id', userId);
  };

