  const handleUpdateBlock = (blockId: string, field: keyof WorkoutBlock, value: string) => {
    if (userRole !== 'COACH') return;
    const newBlocks = activeBlocks.map(b => 
      b.id === blockId ? { ...b, [field]: value } : b
    );
    handleDayChange('blocks', newBlocks);
  };

  const generateId = () => Date.now().toString() + Math.random().toString(36).substr(2, 5);

  const handleAddBlock = () => {
    const newBlock: WorkoutBlock = {
      id: generateId(),
      title: 'Nueva Sección',
      content: ''
    };
    handleDayChange('blocks', [...activeBlocks, newBlock]);
  };

  const handleDuplicateBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const blockToCopy = activeBlocks.find(b => b.id === blockId);
    if (!blockToCopy) return;

    const newBlock: WorkoutBlock = {
      ...blockToCopy,
      id: generateId(),
      title: `${blockToCopy.title} (Copia)`
    };

    const index = activeBlocks.findIndex(b => b.id === blockId);
    const newBlocks = [...activeBlocks];
    newBlocks.splice(index + 1, 0, newBlock);

    handleDayChange('blocks', newBlocks);
  };

  const handleDeleteBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const newBlocks = activeBlocks.filter(b => b.id !== blockId);
    handleDayChange('blocks', newBlocks);
  };

  // --- Input handlers for logging ---
  const handleLogInputChange = (blockId: string, field: 'result' | 'notes', value: string) => {
     setLogInputs(prev => ({
        ...prev,
        [blockId]: {
           ...(prev[blockId] || {result: '', notes: ''}),
           [field]: value
        }
     }));
  };

  const toggleFormVisibility = (blockId: string) => {
    setVisibleForms(prev => ({
      ...prev,
      [blockId]: !prev[blockId]
    }));
    // If closing, clear editing state
    if (visibleForms[blockId]) {
       setEditingLogId(null);
       setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    }
  };

  // Pre-fill form for editing
  const handleEditLog = (e: React.MouseEvent, log: WorkoutLog, blockId: string) => {
     e.stopPropagation();
     setEditingLogId(log.id);
     setLogInputs(prev => ({
        ...prev,
        [blockId]: { result: log.result, notes: log.notes || '' }
     }));
     setVisibleForms(prev => ({ ...prev, [blockId]: true }));
  };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;

    if (editingLogId) {
       // UPDATE EXISTING
       const updatedLog: WorkoutLog = {
          id: editingLogId,
          userId: currentUserId,
          dayId: dayId,
          sectionTitle: blockTitle,
          result: input.result,
          notes: input.notes,
          date: new Date().toISOString() // Or keep original date? Usually updating timestamp is fine or keep original. Let's update date to show recent activity or keep original? For simplicty we update. 
          // Actually, keeping original date is better for history. But we don't have it easily here unless we fetch it. 
          // Let's assume we want to update the content but keep the log entry valid.
       };
       onUpdateLog(updatedLog);
       setEditingLogId(null);
    } else {
       // CREATE NEW
       const log: WorkoutLog = {
         id: Date.now().toString(),
         userId: currentUserId,
         dayId: dayId,
         sectionTitle: blockTitle, 
         result: input.result,
         notes: input.notes,
         date: new Date().toISOString()
       };
       onAddLog(log);
    }

    // Clear input
    setLogInputs(prev => ({
       ...prev,
       [blockId]: {result: '', notes: ''}
    }));

    // Close form
    setVisibleForms(prev => ({
      ...prev,
      [blockId]: false
    }));
  };

  // --- Helper to Render Links & YouTube Embeds ---
  const renderWithLinks = (text: string) => {
    if (!text) return <span className="text-gray-600 italic">Sin contenido...</span>;
    const urlRegex = /((?:https?:\/\/|www\.)[^\s]+)/g;
    const parts = text.split(urlRegex);

    return parts.map((part, i) => {
      if (part.match(urlRegex)) {
        const youtubeRegex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/;
        const youtubeMatch = part.match(youtubeRegex);

        if (youtubeMatch && youtubeMatch[1]) {
          const videoId = youtubeMatch[1];
          return (
            <div key={i} className="block my-3 w-full max-w-md aspect-video rounded-xl overflow-hidden shadow-2xl border border-dark-700 bg-black">
              <iframe
                width="100%" height="100%" src={`https://www.youtube.com/embed/${videoId}`} title="YouTube video player" frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="w-full h-full"
              ></iframe>
            </div>
          );
        }
        const href = part.startsWith('www.') ? `https://${part}` : part;
        return (
          <a key={i} href={href} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:text-blue-300 underline break-all inline-flex items-center gap-0.5 align-top" onClick={(e) => e.stopPropagation()}>
            {part} <ExternalLink size={10} className="inline opacity-70" />
          </a>
        );
      }
      return part;
    });
  };

