        </div>
        <div className="text-center text-[10px] text-gray-500 uppercase tracking-widest font-bold">
           Semana del {programData.startDate}
        </div>
      </div>

      {/* TABS (Calendar Strip) */}
      <div className="flex overflow-x-auto gap-2 px-2 pb-2 mb-2 no-scrollbar shrink-0">
        {programData.days.map((day) => {
          const isSelected = selectedDayId === day.id;
          const dayHasLogs = logs.some(l => l.dayId === day.id && l.userId === currentUserId);
