                ${isSelected 
                  ? 'bg-blood-600 border-blood-500 text-white shadow-lg shadow-blood-900/40 transform scale-105 z-10' 
                  : 'bg-dark-800 border-dark-700 text-gray-400 hover:bg-dark-700'
                }
              `}
            >
              <span className="text-[10px] font-bold uppercase tracking-wider mb-1">{day.dayName.substring(0, 3)}</span>
              <span className="text-lg font-black leading-none mb-1">{formatTabDate(day.date)}</span>

              {dayHasLogs && !day.isRestDay ? (
                 <CheckCircle size={14} className={isSelected ? 'text-white' : 'text-green-500'} />
