                      <AutoResizeTextarea
                         value={block.content}
                         onChange={(e) => handleUpdateBlock(block.id, 'content', e.target.value)}
                         placeholder="Escribe el entrenamiento aquí... (Pega links de YouTube)"
                         className="w-full bg-transparent text-gray-200 font-mono text-sm leading-relaxed focus:outline-none min-h-[60px]"
                      />
                   ) : (
                      <>
                        {block.title && <h3 className="text-xs font-black text-blood-500 uppercase tracking-widest mb-2 border-l-2 border-blood-500 pl-2">{block.title}</h3>}
                        <div className="whitespace-pre-wrap font-mono text-sm text-gray-300 leading-relaxed mb-4">
                           {renderWithLinks(block.content)}
                        </div>

                        {/* --- SECTION LOGGING (ATHLETE) --- */}
                        {!activeDay.isRestDay && (
                           <div className="mt-4 pt-4 border-t border-dark-700/50">
                              {/* History for this block */}
                              {blockLogs.length > 0 && (
                                 <div className="mb-3 space-y-2">
                                    {blockLogs.map(log => (
                                       <div key={log.id} className="flex justify-between items-center bg-dark-900/50 p-2 rounded text-xs border border-dark-700/50">
                                          <div>
                                             <span className="text-blood-400 font-bold mr-2">{log.result}</span>
                                             {log.notes && <span className="text-gray-500 italic">"{log.notes}"</span>}
                                          </div>
                                          <div className="flex items-center gap-2">
                                             <span className="text-gray-600 text-[10px]">{new Date(log.date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>

                                             {/* Edit Button */}
                                             <button 
                                                onClick={(e) => handleEditLog(e, log, block.id)}
                                                className="text-gray-600 hover:text-blue-400 transition-colors p-1"
                                                title="Editar Registro"
                                             >
                                                <Edit2 size={12} />
                                             </button>

                                             {/* Delete Button */}
                                             <button
                                                onClick={(e) => { e.stopPropagation(); onDeleteLog(log.id); }}
                                                className="text-gray-600 hover:text-red-500 transition-colors p-1"
                                                title="Eliminar Registro"
                                             >
                                                <Trash2 size={12} />
                                             </button>
                                          </div>
                                       </div>
                                    ))}
                                 </div>
                              )}

                              {/* Input Form Toggle Area */}
                              {!isFormVisible ? (
                                <button 
                                  onClick={() => toggleFormVisibility(block.id)}
                                  className="w-full border border-dark-700/50 bg-dark-800/50 hover:bg-dark-800 text-gray-400 hover:text-white py-2 rounded-lg text-xs font-bold uppercase tracking-widest transition-all flex items-center justify-center gap-2 hover:border-blood-500/50"
                                >
                                   <PlusCircle size={14} /> Registrar Resultado
                                </button>
                              ) : (
                                <div className="animate-fade-in-up bg-dark-800 p-3 rounded-lg border border-dark-700 shadow-xl border-l-4 border-l-blood-600">
                                    <div className="flex items-center justify-between mb-2">
                                       <span className="text-[10px] uppercase font-bold text-gray-400">
                                          {editingLogId ? 'Editando Registro...' : 'Nuevo Registro'}
                                       </span>
                                    </div>
                                    <div className="flex flex-col md:flex-row gap-3">
                                      <div className="flex-1">
                                          <input 
                                            type="text"
                                            placeholder="Resultado (ej: 185 lbs)"
                                            className="w-full bg-dark-900 border border-dark-600 rounded-lg p-3 text-xs text-white focus:border-blood-500 focus:outline-none"
                                            value={logInputs[block.id]?.result || ''}
                                            onChange={(e) => handleLogInputChange(block.id, 'result', e.target.value)}
                                            autoFocus
                                          />
                                      </div>
                                      <div className="flex-1">
                                          <input 
                                            type="text"
                                            placeholder="Notas..."
                                            className="w-full bg-dark-900 border border-dark-600 rounded-lg p-3 text-xs text-white focus:border-blood-500 focus:outline-none"
                                            value={logInputs[block.id]?.notes || ''}
                                            onChange={(e) => handleLogInputChange(block.id, 'notes', e.target.value)}
                                          />
                                      </div>
                                    </div>
                                    <div className="flex gap-2 mt-3">
                                      <button 
                                          onClick={() => toggleFormVisibility(block.id)}
                                          className="flex-1 bg-dark-700 hover:bg-dark-600 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-widest"
                                      >
                                          <X size={16} /> Cancelar
                                      </button>
                                      <button 
                                          onClick={() => handleSaveLogForBlock(activeDay.id, block.title || 'General', block.id)}
                                          disabled={!logInputs[block.id]?.result?.trim()}
                                          className={`flex-[2] text-white p-3 rounded-lg transition-colors flex items-center justify-center gap-2 shadow-lg text-xs font-bold uppercase tracking-widest ${
                                             editingLogId 
                                             ? 'bg-blue-700 hover:bg-blue-600 shadow-blue-900/20' 
                                             : 'bg-blood-600 hover:bg-blood-500 shadow-blood-900/20'
                                          } disabled:opacity-50`}
                                      >
                                          <Save size={16} /> {editingLogId ? 'Actualizar' : 'Guardar'}
                                      </button>
                                    </div>
                                </div>
                              )}
                           </div>
                        )}
                      </>
                   )}
                </div>
               );
             })}

             {/* Coach Add Button */}
             {userRole === 'COACH' && (
                <button 
                  type="button"
                  onClick={handleAddBlock}
                  className="w-full py-4 rounded-xl border-2 border-dashed border-dark-700 text-gray-500 hover:border-blood-500 hover:text-blood-500 hover:bg-blood-900/10 transition-all flex items-center justify-center gap-2 font-bold uppercase text-xs tracking-widest"
                >
                   <Plus size={16} /> Agregar Sección
                </button>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};
